INSERT INTO `articles` (`id`, `user_id`, `category_id`, `title`, `slug`, `excerpt`, `content`, `image`, `image_caption`, `image_source`, `media_type`, `media_badge`, `video_url`, `video_id`, `is_sticky`, `is_slider`, `views_count`, `status`, `published_at`, `created_at`, `updated_at`, `ai_summary`) VALUES 
  ('1', '1', '1', 'Pemerintah Resmi Luncurkan Logo dan Identitas Visual HUT Ke-81 Kemerdekaan RI', 'pemerintah-resmi-luncurkan-logo-dan-identitas-visual-hut-ke-81-kemerdekaan-ri', 'Pemerintah Republik Indonesia melalui Kementerian Sekretariat Negara (Kemensetneg) resmi meluncurkan logo dan identitas visual peringatan Hari Ulang Tahun (HUT) ke-81 Kemerdekaan RI tahun 2026.', '<p>Pemerintah Republik Indonesia melalui Kementerian Sekretariat Negara (Kemensetneg) resmi meluncurkan logo dan identitas visual peringatan Hari Ulang Tahun (HUT) ke-81 Kemerdekaan RI tahun 2026.</p><p>Perkembangan ini mendapatkan perhatian luas dari berbagai elemen masyarakat dan pemangku kepentingan di seluruh tanah air.</p><blockquote>\\\"Komitmen kami adalah terus menyajikan berita terpercaya, akurat, dan mendalam bagi kemajuan bangsa.\\\"</blockquote><p>Langkah strategis ini diharapkan memberikan dampak jangka panjang yang signifikan bagi pembangunan dan kesejahteraan masyarakat Indonesia.</p>', 'articles/art_1_pemerintah-resmi-luncurkan-logo-dan-identitas-visual-hut-ke-81-kemerdekaan-ri.webp', 'Peluncuran Logo dan Identitas Visual HUT Ke-81 Kemerdekaan RI', 'Biro Pers Sekretariat Presiden RI', 'standard', NULL, NULL, NULL, '1', '0', '5431', 'published', '2026-07-01 16:45:37', '2026-08-21 16:55:01', '2026-08-31 12:50:11', ''),
  ('2', '1', '1', 'Warga Sambut Antusias Peresmian Bendungan Meninting, Lombok Barat', 'warga-sambut-antusias-peresmian-bendungan-meninting-lombok-barat', 'Suasana penuh semangat menyambut kedatangan Presiden Prabowo Subianto di kawasan Bendungan Meninting, Kabupaten Lombok Barat, Provinsi Nusa Tenggara Barat (NTB).', '<p>Suasana penuh semangat menyambut kedatangan Presiden Prabowo Subianto di kawasan Bendungan Meninting, Kabupaten Lombok Barat, Provinsi Nusa Tenggara Barat (NTB).</p><p>Perkembangan ini mendapatkan perhatian luas dari berbagai elemen masyarakat dan pemangku kepentingan di seluruh tanah air.</p><blockquote>\\\"Komitmen kami adalah terus menyajikan berita terpercaya, akurat, dan mendalam bagi kemajuan bangsa.\\\"</blockquote><p>Langkah strategis ini diharapkan memberikan dampak jangka panjang yang signifikan bagi pembangunan dan kesejahteraan masyarakat Indonesia.</p>', 'articles/art_2_warga-sambut-antusias-peresmian-bendungan-meninting-lombok-barat.webp', 'Warga menyambut peresmian Bendungan Meninting di Lombok Barat', 'Biro Pers Sekretariat Presiden / PUPR', 'video', '02:07', 'https://www.youtube.com/watch?v=dQw4w9WgXcQ', 'dQw4w9WgXcQ', '0', '1', '4894', 'published', '2026-07-16 08:04:57', '2026-08-21 16:55:02', '2026-08-31 12:47:34', ''),
  ('3', '1', '1', 'Dari Kesulitan Air Menuju Panen Tiga Kali, Warga Sambut Antusias Peresmian Bendungan Meninting di NTB', 'dari-kesulitan-air-menuju-panen-tiga-kali-warga-sambut-antusias-peresmian-bendungan-meninting-di-ntb', 'Kehadiran Bendungan Meninting menjadi babak baru bagi para petani di Lombok Barat yang selama puluhan tahun mengandalkan tadah hujan.', '<p>Kehadiran Bendungan Meninting menjadi babak baru bagi para petani di Lombok Barat yang selama puluhan tahun mengandalkan tadah hujan.</p><p>Perkembangan ini mendapatkan perhatian luas dari berbagai elemen masyarakat dan pemangku kepentingan di seluruh tanah air.</p><blockquote>\\\"Komitmen kami adalah terus menyajikan berita terpercaya, akurat, dan mendalam bagi kemajuan bangsa.\\\"</blockquote><p>Langkah strategis ini diharapkan memberikan dampak jangka panjang yang signifikan bagi pembangunan dan kesejahteraan masyarakat Indonesia.</p>', 'articles/art_3_dari-kesulitan-air-menuju-panen-tiga-kali-warga-sambut-antusias-peresmian-bendungan-meninting-di-ntb.webp', 'Saluran irigasi Bendungan Meninting mengalir ke sawah warga', 'Kementerian PUPR RI', 'photo', '3 Foto', NULL, NULL, '0', '1', '3720', 'published', '2026-07-16 06:39:08', '2026-08-21 16:55:02', '2026-08-31 12:47:34', ''),
  ('4', '1', '1', 'Seskab Teddy: Presiden Prabowo Terima Menlu Qatar, Bahas Penguatan Investasi dan 50 Tahun Hubungan Diplomatik', 'seskab-teddy-presiden-prabowo-terima-menlu-qatar-bahas-penguatan-investasi-dan-50-tahun-hubungan-diplomatik', 'Presiden Republik Indonesia Prabowo Subianto menerima kunjungan kehormatan dari Menteri Luar Negeri Qatar di Istana Negara, Jakarta.', '<p>Presiden Republik Indonesia Prabowo Subianto menerima kunjungan kehormatan dari Menteri Luar Negeri Qatar di Istana Negara, Jakarta.</p><p>Perkembangan ini mendapatkan perhatian luas dari berbagai elemen masyarakat dan pemangku kepentingan di seluruh tanah air.</p><blockquote>\\\"Komitmen kami adalah terus menyajikan berita terpercaya, akurat, dan mendalam bagi kemajuan bangsa.\\\"</blockquote><p>Langkah strategis ini diharapkan memberikan dampak jangka panjang yang signifikan bagi pembangunan dan kesejahteraan masyarakat Indonesia.</p>', 'articles/art_4_seskab-teddy-presiden-prabowo-terima-menlu-qatar-bahas-penguatan-investasi-dan-50-tahun-hubungan-diplomatik.webp', 'Pertemuan bilateral Presiden Prabowo dengan Menlu Qatar di Istana Merdeka', 'Sekretariat Kabinet RI', 'standard', NULL, NULL, NULL, '0', '1', '2951', 'published', '2026-07-02 15:19:28', '2026-08-21 16:55:02', '2026-08-31 12:47:34', ''),
